export const code = async (inputs) => {
  let rows = [];
  const raw = inputs.reports;
  if (Array.isArray(raw)) {
    rows = raw;
  } else if (raw && typeof raw === 'object') {
    const objVals = Object.values(raw);
    if (objVals.length > 0 && objVals[0] && typeof objVals[0] === 'object' && (objVals[0] as any).values) {
      rows = objVals;
    } else {
      rows = raw.data || raw.rows || objVals;
      if (!Array.isArray(rows)) rows = [rows];
    }
  }

  const reports = rows.map((r) => {
    const row = r as any;
    const v = (row && row.values) ? row.values : (row || {});
    // Reports sheet: A=Report_ID, B=Trip_ID, C=User_ID, D=Total_Expense, E=Generated_Date, F=Report_URL
    return {
      report_id:      String(v.A || row.Report_ID || '').trim(),
      trip_id:        String(v.B || row.Trip_ID || '').trim(),
      user_id:        String(v.C || row.User_ID || '').trim(),
      total_expense:  parseFloat(v.D || row.Total_Expense || 0),
      generated_date: String(v.E || row.Generated_Date || '').trim(),
      report_url:     String(v.F || row.Report_URL || '').trim()
    };
  });

  const response = { success: true, reports: reports };
  return { response_body: JSON.stringify(response) };
};
